# Dual-Z alignment on the optical limit switches of the Creality Hi (F018)
#
# Port of the stock Creality Hi z_align.py (V1.1.0.60) to Kalico. The Hi is a
# bed slinger: Z moves the X gantry on two lead screws (stepper_z and
# stepper_z1) and the two optical switches sit at the TOP of the travel.
# ZDOWN keeps its stock name (inherited from the K2, where the bed drops),
# but on the Hi it RAISES the gantry until both switches trigger and levels
# the two screws against them. The motion is generated by the main MCU
# (config_z_align / query_z_align), not by the host.
#
# Differences from the stock module:
# - No Creality core patches: the status reply is read with a registered
#   response handler, the switches with [buttons], errors are plain G-code
#   errors.
# - A timeout or too many retries raises an error (stock reported it and
#   carried on). On timeout the motors are switched off: the Hi MCU has no
#   command to stop a running alignment.
# - After a successful ZDOWN Z is set to "zmax" (default: position_max of
#   stepper_z). Stock restored a measured zmax and the last Z_TILT_ADJUST
#   correction (ADJUST_STEPPERS); here run Z_TILT_ADJUST after homing.
# - UP_SAFE_Z waits for the MCU to finish (stock returned after one second).
#
# Not usable with the K2 z_align.py: the Hi MCU has no safeDist argument
# and no z_align_force_stop command.
#
# [z_align_hi]
# quick_speed: 20        # mm/s, fast approach to the switches
# slow_speed: 5          # mm/s, final approach
# rising_dist: 5         # mm, back-off after the first trigger
# safe_rising_dist: 15   # mm, travel of UP_SAFE_Z
# filter_cnt: 10         # consecutive samples that count as a trigger
# timeout: 30            # s, for one MCU attempt
# retries: 7             # attempts until the two screws agree
# retry_tolerance: 10    # steps, allowed difference between the screws
# endstop_pin_z: PB15    # optical switch of stepper_z
# endstop_pin_z1: PB14   # optical switch of stepper_z1
# zd_up: 0               # dir pin level that moves away from the switch
# zes_untrig: 0          # switch pin level when not triggered
# zmax:                  # Z set after ZDOWN (default stepper_z position_max)
#
# This file may be distributed under the terms of the GNU GPLv3 license.
import logging

Z_STEPPERS = ("stepper_z", "stepper_z1")
QUERY_ARGS = (
    " oid=%c enable=%c quickSpeed=%u slowSpeed=%u risingDist=%u filterCnt=%c"
)
# Seconds given to the MCU before the first look at its status (as stock).
START_DELAY = 1.0
POLL_INTERVAL = 0.1
# CHECK_ZLIMIT: distance moved away from a triggered switch, and its speed.
BACKOFF_DIST = 0.5
BACKOFF_SPEED = 10.0


class ZAlignTimeout(Exception):
    pass


class ZAlignHi:
    def __init__(self, config):
        self.printer = config.get_printer()
        self.reactor = self.printer.get_reactor()
        self.gcode = self.printer.lookup_object("gcode")
        self.quick_speed = config.getfloat("quick_speed", above=0.0)
        self.slow_speed = config.getfloat("slow_speed", above=0.0)
        self.rising_dist = config.getfloat("rising_dist", above=0.0)
        self.safe_rising_dist = config.getfloat("safe_rising_dist", above=0.0)
        self.filter_cnt = config.getint("filter_cnt", minval=1, maxval=255)
        self.timeout = config.getfloat("timeout", above=0.0)
        self.retries = config.getint("retries", minval=1)
        self.retry_tolerance = config.getint("retry_tolerance", minval=1)
        self.zd_up = config.getint("zd_up", minval=0, maxval=1)
        self.zes_untrig = config.getint("zes_untrig", minval=0, maxval=1)
        ppins = self.printer.lookup_object("pins")
        self.endstop_pins = []
        for option in ("endstop_pin_z", "endstop_pin_z1"):
            pin = config.get(option)
            params = ppins.parse_pin(pin)
            if params["chip_name"] != "mcu" or params["invert"]:
                raise config.error(
                    "z_align_hi: %s must be a plain pin of the main mcu"
                    " (polarity is set with zes_untrig)" % (option,)
                )
            self.endstop_pins.append(params["pin"])
        self.step_pins = []
        self.dir_pins = []
        self.full_steps = None
        for name in Z_STEPPERS:
            section = config.getsection(name)
            step = ppins.parse_pin(section.get("step_pin"), can_invert=True)
            direction = ppins.parse_pin(section.get("dir_pin"), can_invert=True)
            if step["chip_name"] != "mcu" or direction["chip_name"] != "mcu":
                raise config.error(
                    "z_align_hi: %s must be on the main mcu" % (name,)
                )
            self.step_pins.append(step["pin"])
            self.dir_pins.append(direction["pin"])
        z_section = config.getsection("stepper_z")
        self.zmax = config.getfloat("zmax", z_section.getfloat("position_max"))
        self.mcu = self.printer.lookup_object("mcu")
        self.oid_down = self.mcu.create_oid()
        self.oid_up = self.mcu.create_oid()
        self.mcu.register_config_callback(self._build_config)
        self.cmd_down = self.cmd_up = None
        self.step_dist = None
        self.status = {}
        self.limit_state = [False, False]
        self.zdown_switch_enable = 1
        self.aligned = False
        self.last_delta = None
        # A switch reads "triggered" when its pin leaves the untriggered level.
        prefix = "!" if self.zes_untrig else ""
        buttons = self.printer.load_object(config, "buttons")
        buttons.register_buttons(
            [prefix + pin for pin in self.endstop_pins], self._handle_buttons
        )
        self.printer.register_event_handler(
            "klippy:connect", self._handle_connect
        )
        self.printer.register_event_handler(
            "stepper_enable:motor_off", self._handle_motor_off
        )
        self.gcode.register_command(
            "ZDOWN", self.cmd_ZDOWN, desc=self.cmd_ZDOWN_help
        )
        self.gcode.register_command(
            "UP_SAFE_Z", self.cmd_UP_SAFE_Z, desc=self.cmd_UP_SAFE_Z_help
        )
        self.gcode.register_command(
            "CHECK_ZLIMIT",
            self.cmd_CHECK_ZLIMIT,
            desc=self.cmd_CHECK_ZLIMIT_help,
        )
        self.gcode.register_command(
            "ZDOWN_SWITCH",
            self.cmd_ZDOWN_SWITCH,
            desc=self.cmd_ZDOWN_SWITCH_help,
        )

    # MCU setup
    def _build_config(self):
        for name, oid in (
            ("config_z_align", self.oid_down),
            ("config_z_align_up", self.oid_up),
        ):
            self.mcu.add_config_cmd("%s oid=%d" % (name, oid))
            for index in range(len(Z_STEPPERS)):
                self.mcu.add_config_cmd(
                    "%s_add oid=%d z_indx=%d zs_pin=%s zd_pin=%s zd_up=%d"
                    " zes_pin=%s zes_untrig=%d"
                    % (
                        name,
                        oid,
                        index,
                        self.step_pins[index],
                        self.dir_pins[index],
                        self.zd_up,
                        self.endstop_pins[index],
                        self.zes_untrig,
                    )
                )
        self.cmd_down = self.mcu.lookup_command("query_z_align" + QUERY_ARGS)
        self.cmd_up = self.mcu.lookup_command("query_z_align_up" + QUERY_ARGS)
        for oid in (self.oid_down, self.oid_up):
            self.mcu.register_response(
                self._handle_status, "z_align_status", oid
            )

    def _handle_connect(self):
        toolhead = self.printer.lookup_object("toolhead")
        steppers = {
            s.get_name(): s for s in toolhead.get_kinematics().get_steppers()
        }
        for name in Z_STEPPERS:
            if name not in steppers:
                raise self.printer.config_error(
                    "z_align_hi requires [%s]" % (name,)
                )
        self.step_dist = steppers["stepper_z"].get_step_dist()

    def _handle_status(self, params):
        self.status[params["oid"]] = dict(params)

    def _handle_buttons(self, eventtime, state):
        self.limit_state = [bool(state & 1), bool(state & 2)]

    def _handle_motor_off(self, *args):
        self.aligned = False

    # Unit conversions, as the stock module computes them
    def speed_to_ticks(self, speed):
        freq = self.mcu.get_constant_float("CLOCK_FREQ")
        return int(self.step_dist / speed * freq)

    def dist_to_steps(self, dist):
        return int(dist / self.step_dist)

    def query_args(self, oid, rising_dist):
        return [
            oid,
            1,
            self.speed_to_ticks(self.quick_speed),
            self.speed_to_ticks(self.slow_speed),
            self.dist_to_steps(rising_dist),
            self.filter_cnt,
        ]

    # One MCU run: send the request and wait for flag=1 in z_align_status
    def run_mcu(self, cmd, oid, rising_dist):
        args = self.query_args(oid, rising_dist)
        self.status.pop(oid, None)
        cmd.send(args)
        logging.info("z_align_hi: sent %s", args)
        if self.mcu.is_fileoutput():
            return 0
        start = self.reactor.monotonic()
        self.reactor.pause(start + START_DELAY)
        while True:
            status = self.status.get(oid, {})
            if status.get("flag", 0) == 1:
                return int(status.get("deltaError1", 0))
            now = self.reactor.monotonic()
            if now - start > self.timeout:
                raise ZAlignTimeout(
                    "no result after %.0fs, last status %s"
                    % (self.timeout, status)
                )
            self.reactor.pause(now + POLL_INTERVAL)

    def _enable_z(self):
        # The MCU moves the motors itself; the host only has to accept the
        # enable request, so Z is marked as homed where it is (as stock).
        # Returns the toolhead and whether Z was already homed.
        toolhead = self.printer.lookup_object("toolhead")
        now = self.reactor.monotonic()
        was_homed = "z" in toolhead.get_status(now)["homed_axes"]
        toolhead.set_position(toolhead.get_position(), homing_axes="z")
        for name in Z_STEPPERS:
            self.gcode.run_script_from_command(
                "SET_STEPPER_ENABLE STEPPER=%s ENABLE=1" % (name,)
            )
        toolhead.wait_moves()
        return toolhead, was_homed

    def _forget_z(self, toolhead):
        # The host position of Z means nothing after an MCU move.
        toolhead.get_kinematics().clear_homing_state("z")

    def _abort(self, gcmd, msg):
        # The MCU cannot be told to stop: cut the motor drivers instead.
        self.aligned = False
        self.printer.lookup_object("stepper_enable").motor_off()
        return gcmd.error("z_align_hi: %s. Motors are off." % (msg,))

    # Limit switches
    def check_zlimit(self, gcmd):
        if not any(self.limit_state):
            return
        # A switch is already triggered: back both screws off and look again.
        for name in Z_STEPPERS:
            self.gcode.run_script_from_command(
                "FORCE_MOVE STEPPER=%s DISTANCE=-%.3f VELOCITY=%.1f"
                % (name, BACKOFF_DIST, BACKOFF_SPEED)
            )
        self.printer.lookup_object("toolhead").wait_moves()
        self.reactor.pause(self.reactor.monotonic() + 1.0)
        if any(self.limit_state):
            names = [
                name
                for name, state in zip(Z_STEPPERS, self.limit_state)
                if state
            ]
            raise gcmd.error(
                "z_align_hi: Z limit switch still triggered after backing off"
                " (%s): faulty switch or gantry badly tilted"
                % (", ".join(names),)
            )

    cmd_CHECK_ZLIMIT_help = "Check that the Z optical limit switches are free"

    def cmd_CHECK_ZLIMIT(self, gcmd):
        self.check_zlimit(gcmd)
        gcmd.respond_info("z_align_hi: Z limit switches free")

    cmd_ZDOWN_SWITCH_help = "Enable or skip ZDOWN in the next Z homing macro"

    def cmd_ZDOWN_SWITCH(self, gcmd):
        self.zdown_switch_enable = gcmd.get_int("ENABLE", 1, minval=0, maxval=1)

    cmd_UP_SAFE_Z_help = "Raise the gantry by safe_rising_dist (MCU move)"

    def cmd_UP_SAFE_Z(self, gcmd):
        self.check_zlimit(gcmd)
        toolhead, was_homed = self._enable_z()
        self.aligned = False
        try:
            self.run_mcu(self.cmd_up, self.oid_up, self.safe_rising_dist)
        except ZAlignTimeout as e:
            raise self._abort(gcmd, "UP_SAFE_Z: %s" % (e,))
        self._forget_z(toolhead)
        gcmd.respond_info("z_align_hi: UP_SAFE_Z done, Z is not homed")

    cmd_ZDOWN_help = "Raise the gantry to the Z limit switches and level it"

    def cmd_ZDOWN(self, gcmd):
        # As the stock Z homing: both switches triggered before starting
        # means a faulty switch or a badly tilted gantry.
        if all(self.limit_state):
            raise gcmd.error(
                "z_align_hi: both Z limit switches are triggered before ZDOWN"
            )
        heater = self.printer.lookup_object("extruder").get_heater()
        old_target = heater.get_status(self.reactor.monotonic())["target"]
        self.gcode.run_script_from_command("M104 S0")
        toolhead, was_homed = self._enable_z()
        self.aligned = False
        delta = None
        try:
            for attempt in range(self.retries):
                delta = self.run_mcu(
                    self.cmd_down, self.oid_down, self.rising_dist
                )
                self.last_delta = delta
                gcmd.respond_info(
                    "z_align_hi: attempt %d, difference %d steps"
                    % (attempt + 1, delta)
                )
                if abs(delta) < self.retry_tolerance:
                    break
            else:
                self._forget_z(toolhead)
                raise gcmd.error(
                    "z_align_hi: ZDOWN not aligned after %d attempts"
                    " (difference %d steps, tolerance %d)"
                    % (self.retries, delta, self.retry_tolerance)
                )
        except ZAlignTimeout as e:
            raise self._abort(gcmd, "ZDOWN: %s" % (e,))
        finally:
            self.gcode.run_script_from_command("M104 S%.1f" % (old_target,))
        # The gantry is at the top, against the switches.
        pos = toolhead.get_position()
        pos[2] = self.zmax
        toolhead.set_position(pos, homing_axes="z")
        self.aligned = True
        gcmd.respond_info(
            "z_align_hi: ZDOWN done, Z set to %.3f" % (self.zmax,)
        )

    def get_status(self, eventtime):
        return {
            "zdown_switch_enable": self.zdown_switch_enable,
            "aligned": self.aligned,
            "last_delta": self.last_delta,
            "limit_z": self.limit_state[0],
            "limit_z1": self.limit_state[1],
        }


def load_config(config):
    return ZAlignHi(config)
